$p='outputs/handcricket.html'
$s=Get-Content -LiteralPath $p -Raw
$s=$s.Replace("function tone(freq=440,dur=.11,type='sine',vol=.06){if(!S.sound||!S.fxOn)return;try{ac??=new audio();const o=ac.createOscillator(),g=ac.createGain();", "function tone(freq=440,dur=.11,type='sine',vol=.06){if(!S.sound||S.effectsVolume<=0)return;try{ac??=new audio();if(ac.state==='suspended')ac.resume();const o=ac.createOscillator(),g=ac.createGain();")
$s=$s.Replace("function musicStart(){if(S.musicTimer||!S.musicOn||S.musicVolume<=0)return;let step=0;", "function musicStart(){if(S.musicTimer||!S.musicOn||S.musicVolume<=0)return;try{ac??=new audio();if(ac.state==='suspended')ac.resume()}catch(e){}let step=0;")
$s=$s.Replace("function setOpponentLine(text){$('#opponentLine').textContent=text}", "function setOpponentLine(text){$('#opponentLine').textContent=text}\nfunction setOpponentEmotion(mood,text){const face={friendly:'🦊',focused:'😼',surprised:'😮',proud:'😎',supportive:'🥹',celebrating:'🤩',sheepish:'😅',thinking:'🤔'};const pal=$('#opponentPersona');pal.dataset.mood=mood;$('#opponentFace').textContent=face[mood]||face.friendly;pal.classList.remove('react');void pal.offsetWidth;pal.classList.add('react');setOpponentLine(text)}\ndocument.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(S.sound&&S.effectsVolume>0)tone(560,.045,'triangle',.025);if(S.musicOn)musicStart()},true);")
$s=$s.Replace("setOpponentLine(S.firstBatter==='you'?'Great toss, Siddhanth! I’ll keep it friendly… but I’m still going for the win!':'My turn to bat! Show me your best delivery, Siddhanth.')", "setOpponentEmotion('surprised',S.firstBatter==='you'?'Great toss, Siddhanth! I’ll keep it friendly… but I’m still going for the win!':'My turn to bat! Show me your best delivery, Siddhanth.')")
$s=$s.Replace("setOpponentLine(batter==='you'?'Your turn at the crease, Siddhanth. I’m cheering for you—mostly!':'I’m batting now! Give me your best ball, Siddhanth.')", "setOpponentEmotion(batter==='you'?'supportive':'focused',batter==='you'?'Your turn at the crease, Siddhanth. I’m cheering for you—mostly!':'I’m batting now! Give me your best ball, Siddhanth.')")
$s=$s.Replace("setOpponentLine('Here come the two beats… you’ve got this, Siddhanth!')", "setOpponentEmotion('focused','Here come the two beats… you’ve got this, Siddhanth!')")
$s=$s.Replace("setOpponentLine('No stress, Siddhanth—the ball doesn’t count. Reset your hands and we’ll try again!')", "setOpponentEmotion('supportive','No stress, Siddhanth—the ball doesn’t count. Reset your hands and we’ll try again!')")
$s=$s.Replace("setOpponentLine(out?(S.batting==='you'?'Ah, unlucky, Siddhanth! Shake it off—you’ve got the next one.':'What a wicket, Siddhanth! That was brilliant bowling!'):(S.batting==='you'?'Lovely shot, Siddhanth! Keep that rhythm going.':'Nice ball, Siddhanth! I’ll have to think faster next time.'))", "setOpponentEmotion(out?(S.batting==='you'?'supportive':'surprised'):(S.batting==='you'?(runs>=4?'celebrating':'proud'):(runs===0?'thinking':'sheepish')),out?(S.batting==='you'?'Ah, unlucky, Siddhanth! Shake it off—you’ve got the next one.':'What a wicket, Siddhanth! That was brilliant bowling!'):(S.batting==='you'?(runs>=4?'What a shot, Siddhanth! That one flew!':'Lovely shot, Siddhanth! Keep that rhythm going.'):(runs===0?'Dot ball! I’ll need to read your next move.':'Nice ball, Siddhanth! I’ll have to think faster next time.')))")
$s=$s.Replace("$('#pepTalk').onclick=()=>{setOpponentLine(pepLines[Math.floor(Math.random()*pepLines.length)]);tone(660,.13)}", "$('#pepTalk').onclick=()=>{setOpponentEmotion('supportive',pepLines[Math.floor(Math.random()*pepLines.length)]);tone(660,.13)}")
$s=$s.Replace("let loadTimer=null,loadFinishTimer=null,loadProgress=0;const loadNotes=['Preparing the crease…','Polishing the pitch…','Warming up your rival…','Checking the stadium lights…'];function finishLoading(){clearInterval(loadTimer);clearTimeout(loadFinishTimer);$('#loadingScreen').classList.add('done');$('#homeStart').focus()}function setLoadProgress(n){loadProgress=Math.min(100,n);$('#loadBar').style.width=loadProgress+'%';$('#loadPercent').textContent=Math.round(loadProgress)+'%';$('.load-track').setAttribute('aria-valuenow',Math.round(loadProgress));$('#loadCopy').textContent=loadNotes[Math.min(loadNotes.length-1,Math.floor(loadProgress/27))];if(loadProgress>=100){$('#enterGame').disabled=false;$('#enterGame').textContent='ENTER THE STADIUM';if(!loadFinishTimer)loadFinishTimer=setTimeout(finishLoading,700)}}$('#enterGame').onclick=finishLoading;$('#skipLoading').onclick=finishLoading;$('#skipLoading').focus();loadTimer=setInterval(()=>setLoadProgress(loadProgress+13),120);window.addEventListener('load',()=>setLoadProgress(Math.max(loadProgress,76)),{once:true});", "let loadTimer=null,loadProgress=0;const loadNotes=['Preparing the crease…','Polishing the pitch…','Warming up your rival…','Checking the stadium lights…'];function finishLoading(){if($('#loadingScreen').classList.contains('opening')||$('#loadingScreen').classList.contains('done'))return;clearInterval(loadTimer);setLoadProgress(100);$('#loadingScreen').classList.add('opening');$('#homeScreen').classList.add('entering');musicStart();setTimeout(()=>{$('#loadingScreen').classList.add('done');$('#homeStart').focus()},780)}function setLoadProgress(n){loadProgress=Math.min(100,n);$('#loadBar').style.width=loadProgress+'%';$('#loadPercent').textContent=Math.round(loadProgress)+'%';$('.load-track').setAttribute('aria-valuenow',Math.round(loadProgress));$('#loadCopy').textContent=loadProgress>=100?'Stadium ready. Tap to enter.':loadNotes[Math.min(loadNotes.length-1,Math.floor(loadProgress/27))];if(loadProgress>=100){$('#loadingScreen').classList.add('ready');$('#enterGame').disabled=false;$('#enterGame').textContent='ENTER THE STADIUM';$('#skipLoading').disabled=true;$('#skipLoading').textContent='READY'}}$('#enterGame').onclick=finishLoading;$('#skipLoading').onclick=()=>setLoadProgress(100);$('#skipLoading').focus();$('#skipToGame').onclick=e=>{e.preventDefault();finishLoading()};loadTimer=setInterval(()=>setLoadProgress(loadProgress+13),120);window.addEventListener('load',()=>setLoadProgress(Math.max(loadProgress,76)),{once:true});")
Set-Content -LiteralPath $p -Value $s -NoNewline
